pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const fileInput=document.getElementById("file-input"),loading=document.getElementById("loading"),resultArea=document.getElementById("result-area"),scriptContent=document.getElementById("script-content"),dropZone=document.getElementById("drop-zone");function generatePodcastScript(t){loading.style.display="none",resultArea.style.display="block",scriptContent.style.display="block";const e=t.split(/(?<=[.!?])\s+/).filter(t=>t.trim().length>60).slice(0,10),n=[];n.push({speaker:"Alex",text:"Welcome back to the PDFIndi Insight series. Today we're diving into a very interesting document."}),n.push({speaker:"Jordan",text:"Definitely. There is a lot to unpack here. Let's start with the big picture."}),e.forEach((t,e)=>{const o=e%2==0?"Alex":"Jordan",s=e%3==0?"That's a great point. Also, ":"I found this part fascinating: ";n.push({speaker:o,text:s+t})}),n.push({speaker:"Alex",text:"That just about wraps up our dive into this document. Thanks for listening!"});let o="";n.forEach(t=>{o+=`<div class="script-line"><span class="speaker">${t.speaker}</span><p class="dialogue">${t.text}</p></div>`}),scriptContent.innerHTML=o;const s=n.map(t=>`${t.speaker}: ${t.text}`).join("\n\n");setTimeout(()=>{downloadScript(s)},2e3),document.getElementById("download-btn").onclick=()=>downloadScript(s)}function downloadScript(t){const{jsPDF:e}=window.jspdf,n=new e;n.setFontSize(22),n.setTextColor(250,114,32),n.text("AI Podcast Script",20,20),n.setFontSize(10),n.setTextColor(150),n.text("Drafted by PDFIndi AI",20,30),n.setFontSize(11),n.setTextColor(50);const o=n.splitTextToSize(t,170);n.text(o,20,45),n.save("pdfindi-podcast-script.pdf")}fileInput.onchange=async t=>{const e=t.target.files[0];if(e){dropZone.style.display="none",loading.style.display="block";try{const t=await e.arrayBuffer(),n=await pdfjsLib.getDocument(t).promise;let o="";for(let t=1;t<=Math.min(n.numPages,10);t++){const e=await n.getPage(t);o+=(await e.getTextContent()).items.map(t=>t.str).join(" ")+" "}generatePodcastScript(o)}catch(t){alert("Error creating script."),location.reload()}}};